  }) {
    _mediaList = mediaList;
    _hasNext = hasNext;
    _tagMedias = tagMedias;
  }

  Data.fromJson(dynamic json) {
    _mediaList = [];
    _tagMedias = [];
    tagID = [];

    final dynamic decoded = _mediaDecodeJson(json);
    if (decoded is List) {
      _mediaList = decoded
          .whereType<Map>()
          .map((v) => MediaList.fromJson(Map<String, dynamic>.from(v)))
          .toList();
      _hasNext = false;
      return;
    }
    if (decoded is! Map) {
      _hasNext = false;
      return;
    }

    final Map<String, dynamic> map = Map<String, dynamic>.from(decoded);
    final dynamic list = map['MediaList'] ??
        map['mediaList'] ??
        map['list'] ??
        map['records'] ??
        map['rows'] ??
        map['items'];
    if (list is List) {
      _mediaList = list
          .whereType<Map>()
          .map((v) => MediaList.fromJson(Map<String, dynamic>.from(v)))
          .toList();
    }

    final dynamic tagMedias = map['tagMedias'];
    if (tagMedias is Map) {
      final dynamic tagList = tagMedias['mediaList'];
      if (tagList is List) {
        _tagMedias = tagList
            .whereType<Map>()
            .map((v) => MediaList.fromJson(Map<String, dynamic>.from(v)))
            .toList();
      }
      final dynamic tagIds = tagMedias['tagID'];
      if (tagIds is List) {
        tagID = tagIds.map((v) => v.toString()).toList();
      }
    }
    _hasNext = _mediaToBool(map['hasNext']) ?? false;
  }
  List<MediaList>? _mediaList;
  bool? _hasNext;
  List<MediaList>? _tagMedias;

  List<MediaList>? get mediaList => _mediaList;
  List<MediaList>? get tagList => _tagMedias;
  bool? get hasNext => _hasNext;
  List<String> tagID = [];

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    if (_mediaList != null) {
      map['MediaList'] = _mediaList?.map((v) => v.toJson()).toList();
    }
    if (_tagMedias != null) {
      map['_tagMedias'] = _tagMedias?.map((v) => v.toJson()).toList();
    }
    map['hasNext'] = _hasNext;
    return map;
  }
