  MediaList.fromJson(dynamic json) {
    final dynamic decoded = _mediaDecodeJson(json);
    if (decoded is! Map) return;
    final Map<String, dynamic> map = Map<String, dynamic>.from(decoded);
    _id = map['id']?.toString();
    _title = map['title']?.toString();
    _horizontalCover = (map['horizontalCover'] ??
            map['vodHorizontalPic'] ??
            map['vodPic'] ??
            map['cover'])
        ?.toString();
    _verticalCover = (map['verticalCover'] ??
            map['vodVerticalPic'] ??
            map['vodPic'] ??
            map['cover'])
        ?.toString();
    _tags = _mediaStringList(map['tags'] ?? map['themes']);
    _tagNames = _mediaStringList(map['tagNames'] ?? map['tagsSort']);
    _summary = (map['summary'] ?? map['vodIntro'])?.toString();
    _totalEpisode =
        _mediaToInt(map['totalEpisode'] ?? map['vodSerialNumber']) ?? 1;
    _mediaType = (map['mediaType'] ?? 'video')?.toString();
    _kind = _mediaToInt(map['kind'] ?? map['vodClass'] ?? map['groupId']);
    _price = _mediaToInt(map['price'] ?? map['gold']);
    _direction = _mediaToInt(map['direction']);
    _sellType = _mediaToInt(map['sellType']);
    _permission = _mediaToInt(map['permission'] ?? map['status']);
    _general = map['general']?.toString();
    _generalSort = _mediaToInt(map['generalSort']);
    _choice = map['choice']?.toString();
    _choiceSort = _mediaToInt(map['choiceSort']);
    _isActive = _mediaToBool(map['isActive']) ??
        (_mediaToInt(map['status']) == null
            ? null
            : _mediaToInt(map['status']) == 1);
    _countPurchases = _mediaToInt(map['countPurchases'] ?? map['recommend']);
    _countBrowse = _mediaToInt(map['countBrowse'] ?? map['readNumber']);
    _countCollect = _mediaToInt(map['countCollect'] ?? map['collects']);
    _countLike = _mediaToInt(map['countLike'] ?? map['likeNumber']);
    _number = _mediaToInt(map['number']);
    _createdAt = (map['createdAt'] ?? map['createTime'])?.toString();
    _updatedAt = map['updatedAt']?.toString();

    _updateStatus = _mediaToInt(map['updateStatus']);
    _updatedDesc = map['updatedDesc']?.toString();
    horizontalRatio = _mediaToNum(map['horizontalRatio']);
    verticalRatio = _mediaToNum(map['verticalRatio']);
  }
