dynamic _mediaDecodeJson(dynamic raw) {
  if (raw is String) {
    final String s = raw.trim();
    if (s.isEmpty) return null;
    try {
      return json.decode(s);
    } catch (_) {
      return raw;
    }
  }
  return raw;
}

int? _mediaToInt(dynamic v) {
  if (v == null) return null;
  if (v is int) return v;
  if (v is num) return v.toInt();
  if (v is List) return v.length;
  return int.tryParse(v.toString());
}

num? _mediaToNum(dynamic v) {
  if (v == null) return null;
  if (v is num) return v;
  return num.tryParse(v.toString());
}

bool? _mediaToBool(dynamic v) {
  if (v == null) return null;
  if (v is bool) return v;
  if (v is num) return v != 0;
  final String s = v.toString().toLowerCase();
  if (s == 'true' || s == '1') return true;
  if (s == 'false' || s == '0') return false;
  return null;
}

List<String> _mediaStringList(dynamic v) {
  if (v is List) return v.map((e) => e.toString()).toList();
  if (v == null) return <String>[];
  final String s = v.toString().trim();
  return s.isEmpty ? <String>[] : <String>[s];
}
